import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..'),research=path.join(root,'data','research');
const src=JSON.parse(fs.readFileSync(path.join(research,'strategy-lab-v2-historical.json'),'utf8'));
if(!String(src.schemaVersion||'').endsWith('.2'))throw new Error('ENRICHED_STRATEGY_LAB_V2_EVIDENCE_REQUIRED');
const finite=v=>Number.isFinite(Number(v));const round=(v,d=3)=>finite(v)?Number(Number(v).toFixed(d)):null;const avg=x=>x.length?x.reduce((a,b)=>a+b,0)/x.length:null;
const wilson=(k,n,z=1.96)=>{if(!n)return null;const p=k/n,z2=z*z,den=1+z2/n;return Math.max(0,(p+z2/(2*n)-z*Math.sqrt((p*(1-p)+z2/(4*n))/n))/den)*100;};
function deoverlap(rows){const x=[...rows].sort((a,b)=>String(a.signalDate).localeCompare(String(b.signalDate))||String(a.symbol).localeCompare(String(b.symbol))),active=new Map(),out=[];for(const t of x){const u=active.get(t.symbol);if(u&&String(t.signalDate)<=String(u))continue;out.push(t);active.set(t.symbol,t.exitDate||t.signalDate);}return out;}
function matches(x,t={bv:1.4,rv:.75,depth:.45,reclaim:.95,touches:3,rlo:3,rhi:7}){return Number(x.breakoutVolumeRatio)>=t.bv&&Number(x.retestVolumeVsBreakout)<=t.rv&&Number(x.retestDepthAtr)<=t.depth&&Number(x.reclaimVolumeRatio)>=t.reclaim&&Number(x.touches)>=t.touches&&Number(x.riskPct)>=t.rlo&&Number(x.riskPct)<=t.rhi;}
function summary(rows,costPct=.6){const e=deoverlap(rows.filter(x=>x.entered===true)),n=e.length,h=e.filter(x=>x.targetHit).length,s=e.filter(x=>x.stopHit&&!x.targetHit).length,nets=e.map(x=>Number(x.netPct)+.6-costPct),wins=nets.filter(x=>x>0),loss=nets.filter(x=>x<0),gp=wins.reduce((a,b)=>a+b,0),gl=Math.abs(loss.reduce((a,b)=>a+b,0)),rs=e.map(x=>{const r=Number(x.actualRiskPct||x.riskPct);return Number(x.netR)-(costPct-.6)/(r>0?r:999);});return {entered:n,uniqueSymbols:new Set(e.map(x=>x.symbol)).size,hitPct:n?round(h/n*100,1):null,wilson95LowerHitPct:n?round(wilson(h,n),1):null,stopBeforeTargetPct:n?round(s/n*100,1):null,expectancyR:round(avg(rs),3),profitFactor:gl?round(gp/gl,3):(gp>0?'INF':null),averageNetPct:round(avg(nets),3)};}
const all=(src.trades?.retestReclaimV2||[]).filter(x=>x.entered===true),core=all.filter(x=>matches(x));
const periods={discovery:x=>x.signalDate<='2022-12-31',validation:x=>x.signalDate>='2023-01-01'&&x.signalDate<='2024-12-31',holdout:x=>x.signalDate>='2025-01-01'};
const temporal={};for(const [k,fn] of Object.entries(periods))temporal[k]=summary(core.filter(fn));temporal.overall=summary(core);
const byYear={};for(const y of [...new Set(core.map(x=>String(x.signalDate).slice(0,4)))].sort())byYear[y]=summary(core.filter(x=>String(x.signalDate).startsWith(y)));
const costStress={};for(const c of [.6,.8,1,1.2,1.5])costStress[String(c)]=summary(core,c);
const neighborhoods=[];for(const bv of [1.3,1.4,1.5])for(const rv of [.7,.75,.8])for(const depth of [.35,.45,.55])for(const reclaim of [.85,.95,1.05]){const s=summary(all.filter(x=>matches(x,{bv,rv,depth,reclaim,touches:3,rlo:3,rhi:7})));if(s.entered>=50)neighborhoods.push({thresholds:{bv,rv,depth,reclaim},summary:s});}
const hits=neighborhoods.map(x=>x.summary.hitPct).filter(finite).sort((a,b)=>a-b),pfs=neighborhoods.map(x=>Number(x.summary.profitFactor)).filter(finite).sort((a,b)=>a-b);
const selected=deoverlap(core),counts={};for(const x of selected)counts[x.symbol]=(counts[x.symbol]||0)+1;const concentration=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([symbol,count])=>({symbol,count,sharePct:round(count/selected.length*100,1)}));
const leaveOneSymbolOut=[];for(const symbol of Object.keys(counts))leaveOneSymbolOut.push({symbol,...summary(selected.filter(x=>x.symbol!==symbol))});
const checks={overallSize:temporal.overall.entered>=50,overallHit:Number(temporal.overall.hitPct)>=67,overallWilson:Number(temporal.overall.wilson95LowerHitPct)>=55,overallProfitFactor:Number(temporal.overall.profitFactor)>=1.5,holdoutSize:temporal.holdout.entered>=25,holdoutHit:Number(temporal.holdout.hitPct)>=70,holdoutWilson:Number(temporal.holdout.wilson95LowerHitPct)>=58,holdoutProfitFactor:Number(temporal.holdout.profitFactor)>=2,cost1PctExpectancy:Number(costStress['1'].expectancyR)>0,cost1PctProfitFactor:Number(costStress['1'].profitFactor)>=1.2,symbolConcentration:(concentration[0]?.sharePct??100)<=10,thresholdNeighborhoodMedianHit:hits.length?hits[Math.floor(hits.length/2)]>=67:false};
const supportive=Object.values(checks).every(Boolean);
const report={schemaVersion:'sepa-x-full-structure-v3-robustness.1',generatedAt:new Date().toISOString(),researchOnly:true,promotionAllowed:false,automaticEligibilityImpact:'NONE',candidate:{id:'FULL_STRUCTURE_V3',origin:'identified after reviewing 2025-2026 historical holdout; historical results are robustness evidence only, not an independent validation',independentForwardValidationRequired:true,frozenThresholds:{minBreakoutVolumeRatio:1.4,maxRetestVolumeVsBreakout:.75,maxRetestDepthAtr:.45,minReclaimVolumeRatio:.95,minResistanceTouches:3,minRiskPct:3,maxRiskPct:7}},sourceEvidence:{schemaVersion:src.schemaVersion,generatedAt:src.generatedAt},temporal,byYear,costStress,thresholdNeighborhood:{tested:neighborhoods.length,minHitPct:hits[0]??null,medianHitPct:hits.length?hits[Math.floor(hits.length/2)]:null,maxHitPct:hits.at(-1)??null,minProfitFactor:pfs[0]??null,medianProfitFactor:pfs.length?pfs[Math.floor(pfs.length/2)]:null,maxProfitFactor:pfs.at(-1)??null,variants:neighborhoods},symbolConcentration:concentration,leaveOneSymbolOut:{minimumHitPct:leaveOneSymbolOut.length?Math.min(...leaveOneSymbolOut.map(x=>Number(x.hitPct))):null,maximumHitPct:leaveOneSymbolOut.length?Math.max(...leaveOneSymbolOut.map(x=>Number(x.hitPct))):null},robustnessGate:{checks,state:supportive?'ROBUSTNESS_SUPPORTIVE_FORWARD_OOS_REQUIRED':'ROBUSTNESS_NOT_CONFIRMED',promotionAllowed:false,reason:'Candidate was discovered after viewing historical holdout; only new forward observations can provide independent confirmation.'}};
fs.writeFileSync(path.join(research,'strategy-lab-v3-robustness.json'),JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify({temporal,costStress,thresholdNeighborhood:report.thresholdNeighborhood,symbolConcentration:concentration.slice(0,3),gate:report.robustnessGate},null,2));
